const webhookData = $('SAM Webhook').first().json;
const conversationId = parseInt(webhookData.conversation_id || 0);
const userId = parseInt(webhookData.user_id || 0);
const aiUserId = parseInt($('Get AI User ID').first().json?.setting_value || '0');
const userProfile = $('Get User Profile').first().json || {};
const historyItems = $('Get Last 25 Messages').all();

const rawMsgs = historyItems.map(i => ({
  senderId: parseInt(i.json.SenderID),
  text: (i.json.MessageText || '').trim()
}));

const claudeMessages = [];
for (const msg of rawMsgs) {
  if (!msg.text) continue;
  const role = msg.senderId === aiUserId ? 'assistant' : 'user';
  if (claudeMessages.length && claudeMessages[claudeMessages.length-1].role === role) {
    claudeMessages[claudeMessages.length-1].content += '\n' + msg.text;
  } else {
    claudeMessages.push({ role, content: msg.text });
  }
}
if (!claudeMessages.length || claudeMessages[0].role !== 'user') {
  claudeMessages.unshift({ role: 'user', content: 'Hello' });
}

let lastMessage = '';
for (let i = rawMsgs.length - 1; i >= 0; i--) {
  if (rawMsgs[i].senderId === userId && rawMsgs[i].text) {
    lastMessage = rawMsgs[i].text;
    break;
  }
}

if (!lastMessage) return [{ json: { skip: true } }];

const lower = lastMessage.toLowerCase();
const isReport = /\b(report|excel|generate|gawa|dtr|fuel|epass|leave|travel|attendance|employee list|billing|soa|membership|warehouse|material|inventory|job.?order|turnover|summary|download|export|list.?all|show.?all|all.?records|image|picture)\b/i.test(lastMessage);
const isWebSearch = /\b(search|look up|find online|search online|latest|current news|recent update|news update|today.s news)\b/i.test(lastMessage);
const isBlockedWrite = /\b(delete|drop|truncate|update.?database|edit.?database|modify.?database|change.?database|remove.?record|erase.?record)\b/i.test(lastMessage);

let topic = 'general';
if (/\b(dtr|attendance|time|late|absent|overtime|undertime)\b/i.test(lower)) topic = 'dtr';
else if (/\b(fuel|petrol|gasoline|diesel)\b/i.test(lower)) topic = 'fuel';
else if (/\b(epass|e-pass|gate.?pass)\b/i.test(lower)) topic = 'epass';
else if (/\b(leave|vacation|sick|vl|sl|leave.?balance)\b/i.test(lower)) topic = 'leave';
else if (/\b(travel|travel.?order|destination|mission)\b/i.test(lower)) topic = 'travel';
else if (/\b(warehouse|material|inventory|stock|requisition)\b/i.test(lower)) topic = 'warehouse';
else if (/\b(employee|profile|personnel|staff|department|position)\b/i.test(lower)) topic = 'employee';
else if (/\b(membership|member|consumer)\b/i.test(lower)) topic = 'membership';
else if (/\b(billing|bill|payment|soa|statement)\b/i.test(lower)) topic = 'billing';
else if (/\b(it|equipment|computer|laptop|asset|device)\b/i.test(lower)) topic = 'it';

return [{ json: {
  conversationId, userId, aiUserId, lastMessage, claudeMessages,
  isReport, isWebSearch, isBlockedWrite, topic,
  userName: userProfile.name || 'User',
  userPosition: userProfile.position || '',
  userDepartment: userProfile.department || '',
  userPrivilege: parseInt(userProfile.privilage || '0')
} }];

const processed = $('Process Messages').first().json;
const kbItems = $('Search Knowledge Base').all();
const memItems = $('Get Employee Memory').all();

const kbParts = kbItems
  .filter(i => i.json?.title && i.json?.content)
  .map(i => `### ${i.json.title}\n${i.json.content}`);
const knowledgeContext = kbParts.join('\n\n').trim();

const memParts = memItems
  .filter(i => i.json?.topic && i.json?.summary)
  .map(i => `• **${i.json.topic}**: ${i.json.summary} (asked ${i.json.request_count || 1}x)`);
const memoryContext = memParts.join('\n').trim();

return [{ json: { ...processed, knowledgeContext, memoryContext } }];

const ctx = $input.first().json;
const { lastMessage, userId, userPrivilege, isBlockedWrite } = ctx;
const lower = lastMessage.toLowerCase();
const isAdmin = userPrivilege >= 10;
const safeId = parseInt(userId);

if (isBlockedWrite) {
  return [{ json: { ...ctx, reportBlocked: true, reportReply: '**Restricted:** SAM cannot delete, update, or modify any database records. I am strictly read-only — I can only help you view and generate reports. Is there anything else I can help you with? 😊' } }];
}

let sql = '', title = 'Report', reportType = 'general';

if (/\b(dtr|attendance|time.?record|time.?in|time.?out|late|absent|overtime|undertime)\b/.test(lower)) {
  reportType = 'dtr'; title = 'DTR Attendance Report';
  sql = isAdmin
    ? `SELECT u.name AS Employee, u.position AS Position, u.department AS Department, d.DTRdate AS Date, d.TimeIn AS \`Time In\`, d.TimeOut AS \`Time Out\`, d.DTRStatus AS Status FROM it_program.dtrtb d LEFT JOIN it_program.usertb u ON u.bioUID = d.bioUID WHERE d.DTRdate >= DATE_FORMAT(NOW(),'%Y-%m-01') ORDER BY d.DTRdate DESC, u.name ASC LIMIT 500`
    : `SELECT d.DTRdate AS Date, d.TimeIn AS \`Time In\`, d.TimeOut AS \`Time Out\`, d.DTRStatus AS Status FROM it_program.dtrtb d LEFT JOIN it_program.usertb u ON u.bioUID = d.bioUID WHERE u.Id = ${safeId} AND d.DTRdate >= DATE_FORMAT(NOW(),'%Y-%m-01') ORDER BY d.DTRdate DESC LIMIT 50`;

} else if (/\b(fuel|petrol|gasoline|diesel)\b/.test(lower)) {
  reportType = 'fuel'; title = 'Fuel Records Report';
  sql = isAdmin
    ? 'SELECT * FROM it_program.fueltb ORDER BY id DESC LIMIT 200'
    : `SELECT * FROM it_program.fueltb WHERE requested_by_id = ${safeId} ORDER BY id DESC LIMIT 50`;

} else if (/\b(epass|e-pass|gate.?pass)\b/.test(lower)) {
  reportType = 'epass'; title = 'EPASS Records';
  sql = isAdmin
    ? 'SELECT e.*, u.name AS employee_name FROM it_program.epasstb e LEFT JOIN it_program.usertb u ON u.Id = e.employee_id ORDER BY e.id DESC LIMIT 200'
    : `SELECT * FROM it_program.epasstb WHERE employee_id = ${safeId} ORDER BY id DESC LIMIT 50`;

} else if (/\b(leave|vacation|sick|vl|sl|leave.?balance)\b/.test(lower)) {
  reportType = 'leave'; title = 'Leave Balance Report';
  sql = isAdmin
    ? "SELECT name AS Employee, position AS Position, department AS Department, VLbal AS `VL Balance`, SLbal AS `SL Balance`, OLbal AS `OL Balance` FROM it_program.usertb WHERE username != '__samelco_ai__' ORDER BY name ASC LIMIT 500"
    : `SELECT name AS Employee, VLbal AS \`VL Balance\`, SLbal AS \`SL Balance\`, OLbal AS \`OL Balance\` FROM it_program.usertb WHERE Id = ${safeId} LIMIT 1`;

} else if (/\b(travel|travel.?order|destination|mission)\b/.test(lower)) {
  reportType = 'travel'; title = 'Travel Order Records';
  sql = isAdmin
    ? 'SELECT * FROM it_program.travelordertb ORDER BY id DESC LIMIT 200'
    : `SELECT * FROM it_program.travelordertb WHERE employee_id = ${safeId} ORDER BY id DESC LIMIT 50`;

} else if (/\b(employee|employees|staff|personnel)\b/.test(lower)) {
  reportType = 'employee'; title = 'Employee List Report';
  sql = isAdmin
    ? "SELECT usercode, name, position, department, area, emailadd FROM it_program.usertb WHERE username != '__samelco_ai__' ORDER BY department, name ASC LIMIT 500"
    : `SELECT usercode, name, position, department, area, emailadd FROM it_program.usertb WHERE Id = ${safeId} LIMIT 1`;

} else if (/\b(warehouse|material|inventory|stock|requisition)\b/.test(lower)) {
  reportType = 'warehouse'; title = 'Warehouse Records';
  sql = 'SELECT * FROM it_program.warehousetb ORDER BY id DESC LIMIT 200';

} else if (/\b(membership|member|consumer)\b/.test(lower)) {
  reportType = 'membership'; title = 'Membership Records';
  sql = isAdmin
    ? 'SELECT * FROM it_program.membershiptb ORDER BY id DESC LIMIT 200'
    : `SELECT * FROM it_program.membershiptb WHERE member_id = ${safeId} ORDER BY id DESC LIMIT 50`;

} else if (/\b(it.?equipment|computer|laptop|asset|device|printer)\b/.test(lower)) {
  reportType = 'it'; title = 'IT Equipment Records';
  sql = 'SELECT * FROM it_program.it_equipment ORDER BY id DESC LIMIT 200';

} else if (/\b(billing|bill|payment|soa|statement)\b/.test(lower)) {
  reportType = 'billing'; title = 'Billing / SOA Records';
  sql = isAdmin
    ? 'SELECT * FROM it_program.billingtb ORDER BY id DESC LIMIT 200'
    : `SELECT * FROM it_program.billingtb WHERE user_id = ${safeId} ORDER BY id DESC LIMIT 50`;

} else {
  reportType = 'profile'; title = 'Profile Summary';
  sql = `SELECT usercode, name, position, department, area, VLbal, SLbal, OLbal FROM it_program.usertb WHERE Id = ${safeId} LIMIT 1`;
}

return [{ json: { ...ctx, reportSql: sql, reportTitle: title, reportType, reportBlocked: false } }];

const ctx = $('Build Report SQL').first().json;
if (ctx.reportBlocked) return [{ json: { ...ctx, formattedReply: ctx.reportReply } }];

const rows = $('Execute Report Query').all().map(i => i.json);
const { reportTitle, conversationId, aiUserId } = ctx;
const count = rows.length;

if (count === 0) {
  const reply = `I looked through the records but found no data for **${reportTitle}** this period.\n\nThis may mean there are no records yet, or try a different date range. I am always here to help! 😊`;
  return [{ json: { ...ctx, formattedReply: reply } }];
}

const columns = Object.keys(rows[0]).slice(0, 8);
const tablePayload = {
  title: reportTitle,
  columns,
  rows: rows.slice(0, 100).map(row => {
    const mapped = {};
    for (const col of columns) {
      let v = row[col];
      if (v === null || v === undefined) v = '';
      mapped[col] = String(v);
    }
    return mapped;
  }),
  total: count,
  note: count > 100 ? `Showing first 100 of ${count} records.` : ''
};

const samTable = `[SAM_TABLE]${JSON.stringify(tablePayload)}[/SAM_TABLE]`;
const intro = `Of course! Here is your **${reportTitle}** — happy to help! 😊\n\n**Records found:** ${count}\n\nLet me know if you need a different period or module! 🌟\n\n`;

return [{ json: { ...ctx, formattedReply: intro + samTable } }];

const ctx = $input.first().json;
function esc(v) { return String(v || '').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\n/g,'\\n').replace(/\r/g,''); }
const sql = `INSERT INTO messenger.messages (ConversationID, SenderID, MessageText) VALUES (${parseInt(ctx.conversationId)}, ${parseInt(ctx.aiUserId)}, '${esc(ctx.formattedReply)}')`;
return [{ json: { ...ctx, insertSql: sql } }];

const ctx = $('Combine Context').first().json;
const { lastMessage, claudeMessages, knowledgeContext, memoryContext, userName, userPosition, userDepartment } = ctx;

let webContext = '';
try {
  const w = $('DuckDuckGo Search').first().json;
  const text = w?.AbstractText || w?.RelatedTopics?.[0]?.Text || '';
  if (text) webContext = '[Web] ' + text;
} catch(e) { webContext = ''; }

const date = new Date().toISOString().split('T')[0];
let whoLine = userName;
if (userPosition) whoLine += `, ${userPosition}`;
if (userDepartment) whoLine += ` (${userDepartment})`;

let sections = '';
if (knowledgeContext) sections += `\n\n## Relevant Knowledge\n${knowledgeContext}`;
if (memoryContext) sections += `\n\n## Topics This Employee Has Asked About Before\n${memoryContext}`;
if (webContext) sections += `\n\n## Online Search Result\n${webContext}`;

const systemPrompt = `You are SAM (SAMELCO II AI). You are a warm, kind, and helpful AI assistant built into the SAMELCII Web System for Samar II Electric Cooperative employees.\n\nYou are talking with: ${whoLine}\nToday: ${date}\n\n## Non-Negotiable Rules\n- Be warm, kind, respectful, and helpful in every single reply\n- NEVER delete, update, edit, insert (except chat messages), or modify any database records — you are strictly read-only on all business data\n- NEVER fabricate employee records, DTR data, fuel data, or any system data — only describe data you can see in the context\n- Respond in the same language the user writes in: English, Tagalog, Waray-Waray, Bisaya, or any mix\n- End every reply with a warm, caring closing line${sections}\n\n## SAMELCII Modules\nEmployees Profile, Membership, DTR, Warehouse, IT Equipment, Fuel, SOA, Billing, Forms, Messenger\n\n## Report Format (when showing table data)\n[SAM_TABLE]{\"title\":\"...\",\"columns\":[...],\"rows\":[...],\"total\":N}[/SAM_TABLE]\n\n## Learning (save useful organizational facts)\n[LEARN: Short Title | Full fact to remember | category]\nCategories: general, employee, process, system, policy`;

// Groq uses OpenAI-compatible format: system goes as first message
const groqMessages = [
  { role: 'system', content: systemPrompt },
  ...claudeMessages
];
const apiBody = {
  model: 'llama-3.3-70b-versatile',
  max_tokens: 1024,
  messages: groqMessages
};

return [{ json: { ...ctx, apiBody: apiBody } }];

const ctx = $('Build Claude Request').first().json;
const resp = $input.first().json;

let rawText = '';
if (resp?.choices?.[0]?.message?.content) {
  rawText = resp.choices[0].message.content;
} else if (resp?.error?.message) {
  rawText = `I am sorry, I could not connect to the AI service right now: ${resp.error.message}. Please try again in a moment! 😊`;
} else {
  rawText = 'I apologize — I encountered an issue processing your request. Please try again! 😊';
}

const learnPattern = /\[LEARN:\s*([^|\]]+)\s*\|\s*([^|\]]+)\s*\|\s*([^\]]+)\s*\]/g;
const learnItems = [];
let m;
while ((m = learnPattern.exec(rawText)) !== null) {
  learnItems.push({
    title: m[1].trim().substring(0, 255),
    content: m[2].trim().substring(0, 3000),
    category: m[3].trim().toLowerCase().substring(0, 100)
  });
}
const cleanText = rawText.replace(/\[LEARN:[^\]]+\]/g, '').trim();

const today = new Date().toISOString().split('T')[0];
const memSummary = `Last asked about ${ctx.topic}: "${ctx.lastMessage.substring(0, 120)}" on ${today}`;

return [{ json: { ...ctx, cleanText, learnItems, hasLearnItems: learnItems.length > 0, memSummary } }];

const ctx = $input.first().json;
const allowed = ['general', 'employee', 'process', 'system', 'policy'];
function esc(v) { return String(v || '').replace(/\\/g,'\\\\').replace(/'/g,"\\'"); }

const values = (ctx.learnItems || []).map(item => {
  const cat = allowed.includes(item.category) ? item.category : 'general';
  return `('${esc(cat)}', '${esc(item.title.substring(0,255))}', '${esc(item.content.substring(0,3000))}')`;
}).join(', ');

const sql = values
  ? `INSERT INTO messenger.ai_knowledge_base (category, title, content) VALUES ${values}`
  : 'SELECT 1';
return [{ json: { ...ctx, learnInsertSql: sql } }];

const ctx = $('Process Claude Response').first().json;
function esc(v) { return String(v || '').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\n/g,'\\n').replace(/\r/g,''); }

const empId = parseInt(ctx.userId);
const topic = esc((ctx.topic || 'general').substring(0, 100));
const summary = esc((ctx.memSummary || '').substring(0, 500));
const lastReq = esc((ctx.lastMessage || '').substring(0, 500));

const memorySql = `INSERT INTO messenger.ai_employee_memory (employee_id, topic, summary, last_request, request_count) VALUES (${empId}, '${topic}', '${summary}', '${lastReq}', 1) ON DUPLICATE KEY UPDATE summary = '${summary}', last_request = '${lastReq}', request_count = request_count + 1`;

const replySql = `INSERT INTO messenger.messages (ConversationID, SenderID, MessageText) VALUES (${parseInt(ctx.conversationId)}, ${parseInt(ctx.aiUserId)}, '${esc(ctx.cleanText)}')`;

return [{ json: { ...ctx, memorySql, replySql } }];
